/**
 * The types `wiki/fandom/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    FandomWikitextContext
 * depends    —
 * used by    src/wiki/fandom/index, src/wiki/fandom/wikitext, src/wiki/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from wikitext.ts

export interface FandomWikitextContext {
  pageTitle: string
  templates?: Readonly<Record<string, string>>
  transclusions?: Readonly<Record<string, string>>
}
